import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getUserSubscriptions, createSimpleSubscription } from '../services/simpleApi';
import { isAuthenticated } from '../util/auth';
import { useTheme } from '../context/ThemeContext';
import { useToast } from '../context/ToastContext';
import api from '../services/api';
import SimpleQRCode from '../components/SimpleQRCode';

const Subscriptions = () => {
  const { isDarkMode } = useTheme();
  const { success, error: showError } = useToast();
  const [subscriptions, setSubscriptions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [cancellingId, setCancellingId] = useState(null);
  const [showCancelModal, setShowCancelModal] = useState(false);
  const [selectedSub, setSelectedSub] = useState(null);
  const [showPlansModal, setShowPlansModal] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [subscriptionModal, setSubscriptionModal] = useState(false);
  const [loadingSubscription, setLoadingSubscription] = useState(false);
  const [qrPlan, setQrPlan] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    if (!isAuthenticated()) {
      navigate('/login');
      return;
    }
    fetchSubscriptions();
  }, []);

  const fetchSubscriptions = async () => {
    try {
      setLoading(true);
      const res = await getUserSubscriptions();
      setSubscriptions(res.data);
    } catch (err) {
      setError('Failed to load subscriptions');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleCancelSubscription = async () => {
    if (!selectedSub) return;

    try {
      setCancellingId(selectedSub._id);
      console.log('Attempting to cancel subscription:', selectedSub._id, 'Status:', selectedSub.status);
      const response = await api.put(`/simple-subscription/${selectedSub._id}/cancel`);
      console.log('Cancel response:', response.data);
      success('Subscription cancelled successfully');
      setShowCancelModal(false);
      setSelectedSub(null);
      fetchSubscriptions();
    } catch (err) {
      console.error('Cancel subscription error:', err.response?.data || err.message);
      showError(err.response?.data?.message || 'Failed to cancel subscription');
    } finally {
      setCancellingId(null);
    }
  };

  const openCancelModal = (sub) => {
    setSelectedSub(sub);
    setShowCancelModal(true);
  };

  const getStatusStyles = (status) => {
    switch (status) {
      case 'active':
        return {
          bg: 'bg-gradient-to-r from-green-500/20 to-emerald-500/20',
          text: 'text-green-400',
          border: 'border-green-500/40',
          dot: 'bg-green-400'
        };
      case 'pending':
        return {
          bg: 'bg-gradient-to-r from-yellow-500/20 to-amber-500/20',
          text: 'text-yellow-400',
          border: 'border-yellow-500/40',
          dot: 'bg-yellow-400'
        };
      case 'cancelled':
        return {
          bg: 'bg-gradient-to-r from-red-500/20 to-rose-500/20',
          text: 'text-red-400',
          border: 'border-red-500/40',
          dot: 'bg-red-400'
        };
      default:
        return {
          bg: 'bg-gradient-to-r from-gray-500/20 to-slate-500/20',
          text: 'text-gray-400',
          border: 'border-gray-500/40',
          dot: 'bg-gray-400'
        };
    }
  };

  const getPaymentStatusStyles = (status) => {
    switch (status) {
      case 'paid':
        return { text: 'text-green-400', icon: '✓' };
      case 'pending':
        return { text: 'text-yellow-400', icon: '⏳' };
      default:
        return { text: 'text-gray-400', icon: '—' };
    }
  };

  const formatDate = (date) => {
    if (!date) return 'Not set';
    return new Date(date).toLocaleDateString('en-IN', {
      day: 'numeric',
      month: 'short',
      year: 'numeric'
    });
  };

  const getPlanDetails = (planType) => {
    const plans = {
      daily: {
        name: 'Daily Plan',
        price: 49,
        duration: 'day',
        description: 'Fresh milk every single day',
        features: [
          '500ml Milk Per Day',
          'Fresh Morning Delivery',
          'Standard Pricing',
          'No Commitment'
        ],
        color: 'from-blue-500 to-cyan-500',
        shadow: 'shadow-blue-500/25',
        border: 'border-blue-500/30',
        icon: 'M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z'
      },
      weekly: {
        name: 'Weekly Plan',
        price: 299,
        duration: 'week',
        description: '7 days of fresh dairy goodness',
        features: [
          '500ml Milk Per Day',
          'Flexible Delivery',
          '5% Discount Applied',
          'Priority Support'
        ],
        color: 'from-green-500 to-emerald-500',
        shadow: 'shadow-green-500/25',
        border: 'border-green-500/30',
        icon: 'M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z'
      },
      monthly: {
        name: 'Monthly Plan',
        price: 799,
        duration: 'month',
        description: 'Best value for regular families',
        features: [
          '15L Milk Per Month',
          'Custom Schedule',
          '20% Discount',
          'Free Delivery + Priority'
        ],
        color: 'from-purple-500 to-pink-500',
        shadow: 'shadow-purple-500/25',
        border: 'border-purple-500/30',
        icon: 'M13 10V3L4 14h7v7l9-11h-7z'
      }
    };
    return plans[planType] || plans.daily;
  };

  const handleSubscribe = async (planType) => {
    if (!isAuthenticated()) {
      navigate('/login');
      return;
    }
    setSelectedPlan(planType);
    setSubscriptionModal(true);
    setShowPlansModal(false);
  };

  const createSubscriptionHandler = async () => {
    if (!selectedPlan) return;
    try {
      setLoadingSubscription(true);
      const planDetails = getPlanDetails(selectedPlan);
      const subscriptionData = {
        planType: selectedPlan,
        planName: planDetails.name,
        price: planDetails.price
      };
      const response = await createSimpleSubscription(subscriptionData);
      if (response.status === 201 || response.status === 200) {
        success('Subscription created! Complete payment via QR code');
        setQrPlan(planDetails);
        setSubscriptionModal(false);
        fetchSubscriptions();
      }
    } catch (error) {
      showError(error.response?.data?.message || 'Failed to create subscription');
      console.error('Subscription error:', error);
    } finally {
      setLoadingSubscription(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center">
        <div className="text-center">
          <div className="relative w-16 h-16 mx-auto mb-4">
            <div className="absolute inset-0 rounded-full border-4 border-primary-500/20"></div>
            <div className="absolute inset-0 rounded-full border-4 border-primary-500 border-t-transparent animate-spin"></div>
          </div>
          <p className={`text-lg font-medium ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
            Loading subscriptions...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen py-8 px-4">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="mb-10">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center">
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <h1 className={`text-3xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
              My Subscriptions
            </h1>
          </div>
          <p className={`text-base ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
            View and manage your subscription plans
          </p>
        </div>

        {error && (
          <div className="mb-6 p-4 rounded-2xl bg-red-500/10 border border-red-500/30 text-red-400 font-medium">
            {error}
          </div>
        )}

        {/* Filter active and cancelled subscriptions */}
        {(() => {
          const activeSubscriptions = subscriptions.filter(sub => sub.status === 'active');
          const cancelledSubscriptions = subscriptions.filter(sub => sub.status === 'cancelled');

          return (
            <>
              {/* Active Subscriptions Section */}
              <div className="mb-12">
