                      <button
                        onClick={() => setSubscriptionModal(false)}
                        className={`flex-1 px-4 py-3 rounded-xl font-semibold ${
                          isDarkMode
                            ? 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                        }`}
                      >
                        Cancel
                      </button>
                      <button
                        onClick={createSubscriptionHandler}
                        disabled={loadingSubscription}
                        className="flex-1 px-4 py-3 rounded-xl font-semibold bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        {loadingSubscription ? (
                          <div className="flex items-center justify-center gap-2">
                            <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                            <span>Creating...</span>
                          </div>
                        ) : (
                          'Confirm'
                        )}
                      </button>
                    </div>
                  </div>
                );
              })()}
            </div>
          </div>
        )}

        {/* QR Code Modal */}
        {qrPlan && (
          <SimpleQRCode
            plan={qrPlan}
            onClose={() => setQrPlan(null)}
          />
        )}
      </div>
    </div>
  );
};

export default Subscriptions;
